1	"use client";
2	
3	import { useEffect } from "react";
4	
5	/**
6	 * Fires the browser-side "signup" conversion when a freshly registered account
7	 * lands on the dashboard.
8	 *
9	 * `register()` (lib/actions.ts) redirects a completed signup to
10	 * `/dashboard?signup=1`. Registration is a server action that finishes with a
11	 * server-side `redirect`, so there is no client success handler on the form itself
12	 * — this marker is how the completion becomes observable to the pixel. We strip the
13	 * marker immediately (history.replaceState) so a refresh or back-navigation can
14	 * never double-count, then hand off to `window.nxTrack('signup')` (installed by
15	 * ConversionTags). `nxTrack` only exists once the pixel has loaded, which only
16	 * happens after cookie consent — so with no ids or no consent this is a silent
17	 * no-op. Best-effort and non-blocking, exactly like PurchaseTracker.
18	 */
19	export function SignupTracker() {
20	  useEffect(() => {
21	    const params = new URLSearchParams(window.location.search);
22	    if (params.get("signup") !== "1") return;
23	
24	    // Shared event_id from the server-side CAPI CompleteRegistration (register()).
25	    // Passing it as `eventID` lets Meta dedupe the browser pixel event against the
26	    // server event into ONE conversion; without it the two would double-count.
27	    const eventId = params.get("se") ?? undefined;
28	
29	    // Strip the markers before doing anything else so a reload/back cannot re-fire.
30	    params.delete("signup");
31	    params.delete("se");
32	    const qs = params.toString();
33	    window.history.replaceState(
34	      null,
35	      "",
36	      window.location.pathname + (qs ? `?${qs}` : "") + window.location.hash,
37	    );
38	
39	    // The pixel loads afterInteractive and only once consent is granted — retry a
40	    // few seconds for nxTrack to appear, then give up.
41	    let tries = 0;
42	    let timer: ReturnType<typeof setTimeout> | undefined;
43	    const fire = () => {
44	      const nx = (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack;
45	      if (typeof nx === "function") {
46	        try {
47	          nx("signup", eventId ? { eventId } : {});
48	        } catch {
49	          /* best-effort */
50	        }
51	        return;
52	      }
53	      if (tries++ < 40) timer = setTimeout(fire, 250);
54	    };
55	    fire();
56	    return () => {
57	      if (timer) clearTimeout(timer);
58	    };
59	  }, []);
60	
61	  return null;
62	}
