import { checkRateLimit, clientIp } from "./rate-limit";
import { mayDeliverTo } from "./prefs";
import { normalizeEmail } from "./email-normalize";
import { normalizeHeardSource } from "./heard-about";

// ---------- "How did you hear about us?" survey ----------

/**
 * Record the customer's answer to the one-time acquisition survey.
 *
 * `source` is validated against the allowed channel keys + "skipped" + the
 * "other:<free text>" shape (the free text is trimmed, control-stripped and
 * capped ~120 chars — see normalizeHeardSource). An unrecognised value is
 * silently dropped.
 *
 * "Asked once" is enforced at the write: we only set heardAboutUs when it is
 * still null, using an `updateMany` guarded by `heardAboutUs: null`. A second
 * call (or a race between two tabs) after any value — a channel OR "skipped" —
 * is a no-op and never overwrites the first answer. Always returns { ok: true }
 * so the client can close the prompt regardless.
 */
export async function setHeardAboutUs(source: string): Promise<{ ok: true }> {
  const user = await requireUser();
  const value = normalizeHeardSource(source);
  if (!value) return { ok: true };
  await db.user.updateMany({
    where: { id: user.id, heardAboutUs: null },
    data: { heardAboutUs: value },
  });
  return { ok: true };
}

