"use client";

import { useState, useTransition } from "react";
import { createPortal } from "react-dom";
import { setHeardAboutUs } from "@/lib/actions-account";
import { HEARD_OPTIONS, HEARD_OTHER_MAX } from "@/lib/heard-about";

/**
 * One-time "How did you hear about us?" acquisition survey.
 *
 * Rendered from the dashboard layout ONLY when the signed-in customer's
 * `heardAboutUs` is still null and no admin is impersonating them. The layout's
 * server-side null check is the real gate — this component just shows the modal
 * once and then closes for good. The write itself is idempotent
 * (setHeardAboutUs only sets when null), so even a double-submit is safe.
 *
 * The overlay is portaled to document.body: the portal (Shell) wraps content in
 * transformed ancestors, and a `position: fixed` node inside a transformed
 * parent anchors to THAT parent, not the viewport — dropping the modal down the
 * page. Same fix as components/admin/EmailLogViewer.tsx.
 */
export function HeardAboutUsPrompt() {
  // Local visibility. Starts open because the parent only mounts us when the
  // server says heardAboutUs is null; once dismissed it never comes back this
  // session, and the null→value transition keeps it gone on future loads.
  const [open, setOpen] = useState(true);
  const [choice, setChoice] = useState<string | null>(null);
  const [otherText, setOtherText] = useState("");
  const [pending, startTransition] = useTransition();

  if (!open) return null;
  if (typeof document === "undefined") return null;

  const submit = (source: string) => {
    // Close optimistically — the answer is fire-and-forget and the server is the
    // source of truth for "asked once", so we never need to reopen on failure.
    setOpen(false);
    startTransition(async () => {
      try {
        await setHeardAboutUs(source);
      } catch {
        /* best-effort: a failed survey write must never surface an error */
      }
    });
  };

  const answer = () => {
    if (!choice) return;
    if (choice === "other") {
      const text = otherText.trim();
      submit(text ? `other:${text}` : "other");
    } else {
      submit(choice);
    }
  };

  const canSubmit = choice !== null && (choice !== "other" || otherText.trim().length > 0);

  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm motion-safe:animate-[fadeIn_150ms_ease-out]"
      role="dialog"
      aria-modal="true"
      aria-labelledby="heard-title"
    >
      <div className="card w-full max-w-lg p-6" onClick={(e) => e.stopPropagation()}>
        <h2 id="heard-title" className="text-lg font-bold tracking-tight">
          How did you hear about us?
        </h2>
        <p className="mt-1 text-sm text-slate-400">
          Quick one-tap question — it helps us reach more people like you. This won&apos;t be asked again.
        </p>

        <div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-3">
          {HEARD_OPTIONS.map((o) => (
            <button
              key={o.key}
              type="button"
              onClick={() => setChoice(o.key)}
              aria-pressed={choice === o.key}
              className={`rounded-xl border px-3 py-2.5 text-sm font-medium transition-colors ${
                choice === o.key
                  ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                  : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:bg-white/[0.06]"
              }`}
            >
              {o.label}
            </button>
          ))}
          <button
            type="button"
            onClick={() => setChoice("other")}
            aria-pressed={choice === "other"}
            className={`rounded-xl border px-3 py-2.5 text-sm font-medium transition-colors ${
              choice === "other"
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:bg-white/[0.06]"
            }`}
          >
            Other
          </button>
        </div>

        {choice === "other" && (
          <div className="mt-3">
            <input
              type="text"
              autoFocus
              value={otherText}
              maxLength={HEARD_OTHER_MAX}
              onChange={(e) => setOtherText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && canSubmit) answer();
              }}
              placeholder="Tell us where…"
              className="input"
            />
          </div>
        )}

        <div className="mt-6 flex items-center justify-between gap-3">
          <button type="button" onClick={() => submit("skipped")} disabled={pending} className="btn-ghost text-sm">
            Skip
          </button>
          <button type="button" onClick={answer} disabled={!canSubmit || pending} className="btn-primary">
            Submit
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}

export default HeardAboutUsPrompt;

